typedef struct { void* data; unsigned long seq; } slot_t;
typedef struct {
  slot_t* slots;
  size_t cap;
  _Atomic size_t head;
  _Atomic size_t tail;
} queue_t;

bool enqueue(queue_t* q, void* item);
bool dequeue(queue_t* q, void** item);
```

```c
// Minimal pseudo-code (high level)
size_t t = atomic_load_explicit(&q->tail, memory_order_acquire);
size_t h = atomic_load_explicit(&q->head, memory_order_relaxed);
if (t - h >= q->cap) return false; // full
slot_t* s = &q->slots[t & (q->cap-1)];
unsigned long expected = s->seq;
if (CAS(&s->seq, expected, expected+1)) {
  s->data = item;
  atomic_store_explicit(&q->tail, t+1, memory_order_release);
  return true;
}
```

